/**
 * AI 简报生成模块
 * 读取本地课表/考试/待办数据，拼接 1-3 句中文总结
 */

import { calculateCurrentWeek, getTodayCourses, getCurrentCourse, getNextCourse, getSemesterTotalWeeks } from './schedule'
import { getNearestExam, getExamCountdown, getExamStatus } from './exam'
import { getOverdueTasks, getTodayTasks, getTaskSummary } from './task'
import { getWeekday } from './time'

/**
 * 生成每日简报
 * @param {Date} now 当前时间
 * @returns {string} 简报文案
 */
export function generateDailyBrief(now) {
  const parts = []
  const weekday = getWeekday(now)

  // a) 开头段：教学周
  const currentWeek = calculateCurrentWeek(now)
  if (currentWeek > 0) {
    parts.push(`第${currentWeek}周 · ${weekday}`)
  } else {
    parts.push('学期未开始')
  }

  // b) 课程段
  const todayCourses = getTodayCourses(now, currentWeek)
  if (todayCourses.length > 0) {
    let courseText = `今天${todayCourses.length}节课`
    const currentCourse = getCurrentCourse(now, currentWeek)
    if (currentCourse) {
      courseText += `，正在上《${currentCourse.name}》`
    } else {
      const nextCourse = getNextCourse(now, currentWeek)
      if (nextCourse) {
        courseText += `，下一节《${nextCourse.name}》${nextCourse.startTime}`
      }
    }
    parts.push(courseText)
  } else {
    parts.push('今日无课')
  }

  // c) 考试段
  const nearestExam = getNearestExam(now)
  if (nearestExam) {
    const examStatus = getExamStatus(nearestExam, now)
    if (examStatus === 'ongoing') {
      parts.push(`《${nearestExam.course}》正在进行`)
    } else if (examStatus === 'today') {
      parts.push(`今天有考试《${nearestExam.course}》`)
    } else {
      const countdown = getExamCountdown(nearestExam, now)
      if (countdown.isFinished) {
        // 已结束，不添加
      } else if (countdown.unit === '天' && countdown.value > 0) {
        parts.push(`最近考试《${nearestExam.course}》还有${countdown.value}天`)
      } else {
        parts.push(`最近考试《${nearestExam.course}》即将开始`)
      }
    }
  }

  // d) 待办段
  const taskSummary = getTaskSummary(now)
  const overdueTasks = getOverdueTasks(now)
  if (overdueTasks.length > 0) {
    parts.push(`${overdueTasks.length}项待办已逾期，请优先处理`)
  } else if (taskSummary.totalCount > 0) {
    parts.push(`待办${taskSummary.totalCount}项`)
  }

  // e) 空状态
  if (todayCourses.length === 0 && !nearestExam && taskSummary.totalCount === 0) {
    return '今天比较轻松：无课、无考试、无待办。'
  }

  // f) 拼接
  let brief = parts.join('；') + '。'

  // 长度控制在 60 字以内
  if (brief.length > 60 && parts.length > 2) {
    // 省略课程段的"下一节"详情
    const coursePart = parts[1]
    if (coursePart.includes('下一节')) {
      const shortCoursePart = coursePart.split('，')[0]
      parts[1] = shortCoursePart
      brief = parts.join('；') + '。'
    }
  }

  return brief
}

