/**
 * 每日简报生成模块
 * 根据本地课表、考试、待办数据，生成 1～3 句中文总结
 */

import { calculateCurrentWeek, getTodayCourses, getCurrentCourse, getNextCourse } from './schedule'
import { getNearestExam, getExamCountdown } from './exam'
import { getOverdueTasks, getTodayTasks } from './task'
import { getTasks } from './storage'
import { getWeekday } from './time'

/**
 * 生成每日简报
 * @param {Date} now 当前时间
 * @returns {string} 简报文案（1～3 句，分号连接，末尾句号）
 */
export function generateDailyBrief(now) {
  const parts = []
  const weekday = getWeekday(now)
  const currentWeek = calculateCurrentWeek(now)

  // 1. 开头：周次
  if (currentWeek > 0) {
    parts.push(`第${currentWeek}周 · ${weekday}`)
  } else {
    parts.push('学期未开始')
  }

  // 2. 课程
  const todayCourses = getTodayCourses(now)
  if (todayCourses.length > 0) {
    let courseText = `今天${todayCourses.length}节课`
    const currentCourse = getCurrentCourse(now)
    if (currentCourse) {
      courseText += `，正在上《${currentCourse.name}》`
    } else {
      const nextCourse = getNextCourse(now)
      if (nextCourse) {
        courseText += `，下一节${nextCourse.name} ${nextCourse.startTime}`
      }
    }
    parts.push(courseText)
  } else {
    parts.push('今日无课')
  }

  // 3. 考试
  const nearestExam = getNearestExam(now)
  if (nearestExam) {
    const countdown = getExamCountdown(nearestExam, now)
    if (countdown.isOngoing) {
      parts.push(`考试《${nearestExam.course}》进行中`)
    } else if (countdown.status === 'today') {
      parts.push(`今天考《${nearestExam.course}》`)
    } else if (countdown.value > 0) {
      parts.push(`最近考试《${nearestExam.course}》还有${countdown.value}${countdown.unit}`)
    }
  }

  // 4. 待办
  const allTasks = getTasks().filter(t => !t.finished)
  const overdueTasks = getOverdueTasks(now)
  const todayTasks = getTodayTasks(now)

  if (allTasks.length > 0) {
    let taskText = `待办${allTasks.length}项`
    if (overdueTasks.length > 0) {
      taskText += `，${overdueTasks.length}项已逾期请优先处理`
    } else if (todayTasks.length > 0) {
      taskText += '，最近一项今晚截止'
    }
    parts.push(taskText)
  }

  // 5. 空状态
  if (todayCourses.length === 0 && !nearestExam && allTasks.length === 0) {
    return '今天比较轻松：无课、无考试、无待办。'
  }

  // 6. 拼接
  return parts.join('；') + '。'
}

